class Solution:
    def minimumMoves(self, arr):
        from functools import lru_cache
        @lru_cache(None)
        def f(i, j):
            if i > j:
                return 0
            if i == j:
                return 1
            best = 1 + f(i + 1, j)
            for k in range(i + 1, j + 1):
                if arr[k] == arr[i]:
                    inner = f(i + 1, k - 1)
                    rest = f(k + 1, j)
                    best = min(best, inner + rest)
            return best
        return f(0, len(arr) - 1)

