class Solution {
public:
    vector<int> a;
    int memo[105][105];
    int f(int i, int j) {
        if (i > j) return 0;
        if (i == j) return 1;
        int &res = memo[i][j];
        if (res != -1) return res;
        res = 1 + f(i + 1, j);
        for (int k = i + 1; k <= j; k++)
            if (a[k] == a[i])
                res = min(res, f(i + 1, k - 1) + f(k + 1, j));
        return res;
    }
    int minimumMoves(vector<int>& arr) {
        a = arr;
        memset(memo, -1, sizeof(memo));
        return f(0, (int)arr.size() - 1);
    }
};

