class Solution:
    def minimumMoves(self, arr):
        n = len(arr)
        INF = float('inf')
        dp = [[INF] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
            if i:
                dp[i][i - 1] = 0
        for L in range(2, n + 1):
            for i in range(n - L + 1):
                j = i + L - 1
                dp[i][j] = 1 + dp[i + 1][j]
                for k in range(i + 1, j + 1):
                    if arr[k] == arr[i]:
                        left = dp[i + 1][k - 1] if k > i + 1 else 0
                        dp[i][j] = min(dp[i][j], left + dp[k + 1][j])
        return dp[0][n - 1]

