class Solution {
public:
    int minimumMoves(vector<int>& arr) {
        int n = arr.size();
        const int INF = INT_MAX / 2;
        vector<vector<int>> dp(n, vector<int>(n, INF));
        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
            if (i) dp[i][i - 1] = 0;
        }
        for (int L = 2; L <= n; L++)
            for (int i = 0; i + L - 1 < n; i++) {
                int j = i + L - 1;
                dp[i][j] = 1 + dp[i + 1][j];
                for (int k = i + 1; k <= j; k++)
                    if (arr[k] == arr[i]) {
                        int left = (k > i + 1) ? dp[i + 1][k - 1] : 0;
                        dp[i][j] = min(dp[i][j], left + dp[k + 1][j]);
                    }
            }
        return dp[0][n - 1];
    }
};

